import { test, expect } from "@playwright/test";

const baseUrl = "https://teskerti.tn";

test.describe("Consultation du programme mis en avant depuis la page d'accueil", () => {
  test("Affichage des informations des événements", async ({ page }) => {
    // Given l'utilisateur est sur la page d'accueil du site
    await page.goto(baseUrl);

    // Then chaque événement affiché doit inclure sa salle, son prix en TND et sa date
    // Selector for event cards on the homepage – adjust if necessary
    const eventCards = page.locator(".event-card"); // TODO: verify selector

    // Ensure at least one event card is present
    await expect(eventCards).toBeVisible();

    const count = await eventCards.count();
    for (let i = 0; i < count; i++) {
      const card = eventCards.nth(i);

      // Venue – selector may vary; adjust accordingly
      const venueLocator = card.locator(".venue"); // TODO: verify selector
      await expect(venueLocator).toBeVisible();

      // Price in TND – look for text containing a number followed by "TND"
      const priceLocator = card.locator("text=/\\d+\\s*TND/"); // regex for price
      await expect(priceLocator).toBeVisible();

      // Date – look for a date pattern like DD/MM/YYYY
      const dateLocator = card.locator("text=/\\d{2}\\/\\d{2}\\/\\d{4}/");
      await expect(dateLocator).toBeVisible();
    }
  });
});

